class Domain {
	public min: number = 0;
	public max: number = 0;
	constructor(min: number, max: number) {
		this.min = min;
		this.max = max;
	}
}

class Constraint {
	public width: Domain;
	public length: Domain;
	public height: Domain;
}

class WallUnit {
	public height: number = 2;
	public heightGap: number = 0.5;
	public thickness: number = 0.2;
}

export class Dimension {
	public width: number = 37;
	public length: number = 37;
	public height: number = 36;

	public thickness = 3.5;
	public radiusCamera = 0.8;

	public groundY = -9;

	public unitScale = 1;

	public epsilon = 0.005;

	public constraint = new Constraint();

	public WallUnit = new WallUnit();

	constructor() {
		this.constraint.width = new Domain(10, 38);
		this.constraint.length = new Domain(10, 38);
		this.constraint.height = new Domain(20, 38);

		this.WallUnit.height = 1;
		this.WallUnit.heightGap = 0.2;
		this.WallUnit.thickness = 0.2;
	}

	public setSize(width: number, height: number, length: number) {
		this.width = width;
		this.height = height;
		this.length = length;
	}
	public setWidth(value: number) {
		this.width = value;
	}
	public setHeight(value: number) {
		this.height = value;
	}
	public seLength(value: number) {
		this.length = value;
	}
	public getLog() {
		return `
			Width: ${this.width}, 
			Length: ${this.length}, 
			Height: ${this.height}, 
			Thickness: ${this.thickness}, 
			Camera Radius: ${this.radiusCamera},
			Volume approximation: ${this.getVolumeApproximate()}
			`;
	}
	public getVolumeApproximate(digits: number = 2) {
		const offset = this.thickness * 2.0;
		const height = this.height - offset;
		const width = this.width - offset;
		const length = this.length - offset;
		return (height * width * length * this.unitScale).toFixed(digits);
	}
}
