import * as THREE from 'three';
import { ExoSkeletonMeshes } from './ExoSkeletonMeshes';
import { Dimension } from '../Dimension';

export class Skin {
	public exoSkeletonMeshes: ExoSkeletonMeshes;
	public wallPlain: THREE.InstancedMesh[] = [];
	private dimension: Dimension;
	private animating = true;
	private count: number = -1;
	private states: { y: number; currentY: number; angle: number }[] = [];
	private isOpen = true;
	private animationSpeed = 1.25;
	private rollingSpeed = 0.05;
	private maxAngle = Math.PI / 2;

	constructor(exoSkeletonMeshes: ExoSkeletonMeshes) {
		this.exoSkeletonMeshes = exoSkeletonMeshes;
		this.dimension = this.exoSkeletonMeshes.hypercubeParametric.dimension;
		this.init();
	}

	public init() {
		const wallConfigs = this.createWallConfigurations();

		wallConfigs.forEach((config) => {
			const mesh = this.createWallMesh(config);
			this.wallPlain.push(mesh);
			this.addMeshToScene(mesh);
		});
	}

	private createWallConfigurations() {
		const offsetFromSurface = 0.5;
		const baseY = this.dimension.groundY + this.dimension.thickness;

		return [
			{
				name: 'wall-Front',
				position: {
					x: 0,
					y: baseY,
					z: this.dimension.length * 0.5 - offsetFromSurface,
				},
				rotation: { x: 0, y: 0, z: 0 },
			},
			{
				name: 'wall-Back',
				position: {
					x: 0,
					y: baseY,
					z: -this.dimension.length * 0.5 + offsetFromSurface,
				},
				rotation: { x: 0, y: Math.PI, z: 0 },
			},
			{
				name: 'wall-Left',
				position: {
					x: this.dimension.width * 0.5 - offsetFromSurface,
					y: baseY,
					z: 0,
				},
				rotation: { x: 0, y: Math.PI * 0.5, z: 0 },
			},
			{
				name: 'wall-Right',
				position: {
					x: -this.dimension.width * 0.5 + offsetFromSurface,
					y: baseY,
					z: 0,
				},
				rotation: { x: 0, y: Math.PI * 1.5, z: 0 },
			},
		];
	}

	private createWallMesh(config) {
		const geometry = this.exoSkeletonMeshes.geometry;
		const material = this.exoSkeletonMeshes.material;

		this.count = this.calculateWallCount();

		const mesh = new THREE.InstancedMesh(geometry, material, this.count);
		this.setupMeshProperties(mesh, config.name);
		this.populateInstancedMesh(mesh);
		this.applyMeshTransform(mesh, config);

		return mesh;
	}

	private calculateWallCount() {
		const height = this.dimension.WallUnit.height;
		const ysOffset = this.dimension.WallUnit.heightGap;
		const totalHeight = this.dimension.height - this.dimension.thickness;

		return calculateCount(totalHeight, height, ysOffset);
	}

	private setupMeshProperties(mesh: THREE.Mesh, name: string) {
		mesh.name = name;
		mesh.castShadow = true;
		mesh.receiveShadow = true;
	}

	private populateInstancedMesh(mesh: THREE.Mesh) {
		const dummy = new THREE.Object3D();
		const height = this.dimension.WallUnit.height;
		const ysOffset = this.dimension.WallUnit.heightGap;
		const zs = this.dimension.WallUnit.thickness;

		let currentY = 0;

		for (let row = 0; row < this.count; row++) {
			const isEvenRow = row % 2 === 0;
			const z = isEvenRow ? 0 : zs * 0.5;
			const scaleY = isEvenRow ? height : ysOffset;

			dummy.position.set(0, currentY + scaleY / 2, z);
			dummy.scale.set(1, scaleY, zs);
			dummy.rotation.set(0, 0, 0);
			dummy.updateMatrix();

			mesh.setMatrixAt(row, dummy.matrix);

			this.states[row] = {
				y: dummy.position.y,
				currentY: dummy.position.y,
				angle: 0,
			};

			currentY += scaleY;
		}
	}

	private applyMeshTransform(mesh, config) {
		mesh.position.set(config.position.x, config.position.y, config.position.z);
		mesh.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
	}

	private addMeshToScene(mesh) {
		this.exoSkeletonMeshes.hypercubeParametric.configurator.sceneWrapper.scene.add(mesh);
	}

	public rebuild() {
		this.wallPlain.forEach((obj) => {
			this.exoSkeletonMeshes.hypercubeParametric.configurator.sceneWrapper.scene.remove(obj);
		});
		this.wallPlain = [];
		this.states = [];
		this.init();
	}

	public toggleDoor() {
		this.isOpen = !this.isOpen;
		this.animating = !this.animating;
	}

	public update() {
		const limit = this.dimension.height - this.dimension.thickness * 1.5;
		const dummy = new THREE.Object3D();

		const openY = limit * (4 / 5);
		const offsetFromSurface = 1;

		this.wallPlain.forEach((mesh, meshIndex) => {
			if (this.isOpen && this.states[0].currentY > openY) {
				this.animating = false;
				return this.animating;
			}

			for (let i = 0; i < this.count; i++) {
				const state = this.states[i];
				const maxY = limit;
				const baseY = state.y;

				if (this.isOpen) {
					if (state.currentY < maxY) {
						state.currentY += this.animationSpeed;
						if (state.currentY > maxY) state.currentY = maxY;
					}
					if (state.currentY >= limit) {
						state.angle += this.rollingSpeed;
						if (state.angle > this.maxAngle) state.angle = this.maxAngle;
					}
				} else {
					// if (state.angle > 0) {
					// 	state.angle -= this.rollingSpeed;
					// 	if (state.angle < 0) state.angle = 0;
					// } else {
					state.angle = 0;
					state.currentY -= this.animationSpeed;
					if (state.currentY < baseY) state.currentY = baseY;
					// }
				}

				let z = i % 2 === 0 ? 0 : this.dimension.WallUnit.thickness * 0.5;
				let scaleY = i % 2 === 0 ? this.dimension.WallUnit.height : this.dimension.WallUnit.heightGap;

				dummy.position.set(0, state.currentY, z - offsetFromSurface);
				dummy.scale.set(this.dimension.width - this.dimension.thickness * 2 - this.dimension.epsilon, scaleY, this.dimension.WallUnit.thickness);

				if (meshIndex > 1) {
					z = i % 2 === 0 ? 0 : this.dimension.WallUnit.thickness * 0.5;
					scaleY = i % 2 === 0 ? this.dimension.WallUnit.height : this.dimension.WallUnit.heightGap;

					dummy.position.set(0, state.currentY, z - offsetFromSurface);
					dummy.scale.set(this.dimension.length - this.dimension.thickness * 2 - this.dimension.epsilon, scaleY, this.dimension.WallUnit.thickness);
				}

				if (state.currentY >= maxY) {
					dummy.position.set(0, state.currentY, z - offsetFromSurface);
					dummy.rotation.set(state.angle + i, 0, 0);
				} else {
					dummy.position.set(0, state.currentY, z);
					dummy.rotation.set(state.angle, 0, 0);
				}
				dummy.updateMatrix();

				mesh.setMatrixAt(i, dummy.matrix);
			}
			mesh.instanceMatrix.needsUpdate = true;
		});

		return this.animating;
	}
}

const calculateCount = (totalHeight: number, ys: number, ysOffset: number): number => {
	let currentY = 0;
	let count = 0;

	while (true) {
		const height = count % 2 === 0 ? ys : ysOffset;
		if (currentY + height > totalHeight) break;
		currentY += height;
		count++;
	}
	return count;
};
